#ifndef __CPU_O3_CHAOS_RAT_HH__
#define __CPU_O3_CHAOS_RAT_HH__

#include <random>
#include <bitset>

#include "params/CHAOSRAT.hh"
#include "sim/sim_object.hh"
#include "sim/eventq.hh"
#include "cpu/base.hh"
#include "base/output.hh"
#include "cpu/reg_class.hh"   // RegId, PhysRegIdPtr

// o3::CPU (C++ class behind ArmO3CPU) needed in the .cc to reach
// regFile/renameMap/freeList. Forward-declared here (full definition in .cc
// via cpu/o3/cpu.hh) to avoid dragging cpu.hh into the auto-generated params
// wrapper. CHAOSRAT only supports O3CPU; dynamic_cast fails at construct time.
namespace gem5 { namespace o3 { class CPU; } }

namespace gem5
{

class CHAOSRAT : public SimObject
{
  public:
    CHAOSRAT(const CHAOSRATParams &p);
    ~CHAOSRAT();
    void startup() override;  // wire cpu->chaosRAT = this (avoids Param circular ref)

  private:
    enum class Kind { RatEntry, DestTag };
    Kind kind;

    o3::CPU *cpu;                  // dynamic_cast<o3::CPU*> in .cc
    int target_arch_reg;           // X0-X30 = 0-30
    int target_phys_idx_override;  // -1=random bitflip; >=0 directed (controls)
    int flipped_bit;               // which bit of the index to flip; -1 random

    Cycles first_clock, last_clock;
    uint64_t max_faults;
    uint64_t faults_injected_count;
    uint64_t rng_seed;
    bool write_log;

    // B state: pending dest-rename wait
    bool b_pending;                // reached firstClock, waiting for target dest-rename
    bool b_fired;                  // B injection happened
    bool b_degraded_to_a;          // injected write inst committed → table polluted (B→A-like)

    // recorded at inject time (for log + analysis)
    int orig_phys_idx;             // phys index the entry pointed to before corruption
    int corrupted_phys_idx;        // after bit-flip
    uint64_t requested_inject_cycle;
    uint64_t actual_inject_cycle;
    bool idx_out_of_range;         // flipped index out of [0, numPhysIntRegs-1]

    // A: how long the corrupted entry survived before the next rename overwrote it
    int64_t corrupted_entry_lifetime;  // -1 if never overwritten

    EventFunctionWrapper attackEvent;  // A: fires at firstClock (high priority, after rename)
    EventFunctionWrapper readTraceEvent;  // polls corrupted_phys ownership/value after inject

    std::mt19937 rng;
    std::random_device rd;

    OutputStream *log_stream;

    // helpers
    void doInjectA();              // setEntry on frontend renameMap
    void readTraceCheck();         // poll corrupted_phys ownership/value
    bool maybeInjectB(RegId flat_dest_regid, int dest_idx,
                      /*inout*/ PhysRegIdPtr &renamed_first);  // called from renameDestRegs hook
    // query who owns a phys idx at the current moment (for rename_inconsistency covariate)
    int queryOwner(int phys_idx, bool &in_freelist);

    // stats
    struct CHAOSRATStats : public statistics::Group
    {
        statistics::Scalar numFaultsInjected;
        CHAOSRATStats(statistics::Group *parent);
    };
    std::unique_ptr<CHAOSRATStats> stats;

    // public so the Rename stage hook (or a CPU accessor) can call into B
  public:
    // Called by the renameDestRegs hook: if B is pending and this dest matches
    // target_arch_reg, corrupt the dest tag (rename_result.first). Returns true
    // if it fired this call. id is the flattened arch reg id of the dest.
    bool hookRenameDest(const RegId &flat_dest_regid, PhysRegIdPtr &renamed_first);
    // Called by commit.cc:1264 for each committed dest — if the dest tag is the
    // B-corrupted phys, the injected write inst committed → frontend table flows
    // to corrupted value → B degrades to A-state. (defined in .cc — uses cpu->)
    void noteCommitDest(PhysRegIdPtr committed_dest);
    bool isB_degraded_to_a() const { return b_degraded_to_a; }
};

} // namespace gem5
#endif // __CPU_O3_CHAOS_RAT_HH__

