1	#include "CHAOSReg/CHAOSReg.hh"
2	#include "params/CHAOSReg.hh"
3	
4	#include <iostream>
5	#include <fstream>
6	#include <vector>
7	#include <random>
8	#include <bitset>
9	
10	#include "cpu/base.hh"
11	#include "cpu/thread_context.hh"
12	#include "arch/generic/isa.hh"
13	
14	namespace gem5{
15	
16	    CHAOSReg::CHAOSReg(const CHAOSRegParams &p)
17	        : SimObject(p),
18	        cpu(dynamic_cast<BaseCPU *>(p.cpu)),
19	        probability(p.probability),
20	        num_bits_to_change(p.bitsToChange),
21	        first_clock(Cycles(p.firstClock)),
22	        last_clock(Cycles(p.lastClock)),
23	        max_faults(p.maxFaults),
24	        faults_injected_count(0),
25	        rng_seed(p.rngSeed),
26	        max_reg_idx(p.maxRegIdx),
27	        fault_type_enum(stringToFaultType(p.faultType)),
28	        fault_mask(std::bitset<32>(p.faultMask)),
29	        bit_flip_prob(p.bitFlipProb),
30	        stuck_at_zero_prob(p.stuckAtZeroProb),
31	        stuck_at_one_prob(p.stuckAtOneProb),
32	        cycles_permament_fault_check(Cycles(p.cyclesPermamentFaultCheck)),
33	        reg_target_class_enum(stringToTargetClass(p.regTargetClass)),
34	        PC_target(p.PCTarget),
35	        write_log(p.writeLog),
36	        attackEvent([this] { this->attackCheck(); }, name()),
37	        periodicCheck([this] { this->checkPermanent(); }, name() + ".periodicCheck"),
38	        stats(nullptr)
39	    {
40	        if (probability > 0.0){
41	            if (!cpu) {
42	                throw std::runtime_error("CHAOSReg: Invalid CPU pointer.\n");
43	            }
44	
45	            log_stream = simout.create("fault_injections.log", false, true);
46	            if (!log_stream || !log_stream->stream()) {
47	                panic("CHAOSReg: Could not open log file");
48	            }
49	
50	            stats = std::make_unique<CHAOSRegStats>(this);
51	
52	            // Reproducibility: if rng_seed is set (nonzero), use it; otherwise
53	            // fall back to std::random_device (original, non-reproducible).
54	            rng.seed(rng_seed != 0 ? rng_seed : rd());
55	            if (PC_target != 0){
56	                // In this case, it is necessary to check at every cycle if the PC matches, so it is better to set the probability to 1.
57	                probability = 1;
58	            }
59	
60	            if (num_bits_to_change == -1){
61	                std::uniform_int_distribution<int> dist(1, 32);
62	                num_bits_to_change = dist(rng);
63	            }
64	
65	            inter_fault_cycles_dist = std::geometric_distribution<unsigned>(probability);
66	            
67	            unsigned next_fault_cycle_distance = inter_fault_cycles_dist(rng);
68	            scheduleAttackEvent(first_clock + Cycles(next_fault_cycle_distance));
69	            
70	            if ((bit_flip_prob + stuck_at_zero_prob + stuck_at_one_prob) != 1.0){
71	                warn("Sum of probabilities is not 1, assuming 0.9 for bitFlipProb, 0.05 for stuckAtZeroProb and 0.05 for stuckAtOneProb.\n");
72	                bit_flip_prob = 0.9;
73	                stuck_at_zero_prob = 0.05;
74	                stuck_at_one_prob = 0.05;
75	            }
76	
77	            std::vector<double> weights = {bit_flip_prob, stuck_at_zero_prob, stuck_at_one_prob};
78	            random_fault_distribution = std::discrete_distribution<int>(weights.begin(), weights.end());
79	
80	            scheduleCheckPermanentFault(first_clock + cycles_permament_fault_check);
81	        }
82	    }
83	
84	    CHAOSReg::CHAOSRegStats::CHAOSRegStats(statistics::Group *parent)
85	    : statistics::Group(parent),
86	      ADD_STAT(numFaultsInjected, statistics::units::Count::get(),
87	               "Total number of faults injected"),
88	      ADD_STAT(numBitFlips, statistics::units::Count::get(),
89	               "Number of bit flip faults injected"),
90	      ADD_STAT(numStuckAtZero, statistics::units::Count::get(),
91	               "Number of stuck-at-0 faults injected"),
92	      ADD_STAT(numStuckAtOne, statistics::units::Count::get(),
93	               "Number of stuck-at-1 faults injected"),
94	      ADD_STAT(numPermanentFaults, statistics::units::Count::get(),
95	               "Total number of permanent faults injected")
96	    {
97	    }
98	
99	    CHAOSReg::~CHAOSReg(){}
100	
101	    CHAOSReg::FaultType 
102	    CHAOSReg::stringToFaultType(const std::string &s) {
103	        if (s == "bit_flip") return FaultType::BitFlip;
104	        else if (s == "stuck_at_zero") return FaultType::StuckAtZero;
105	        else if (s == "stuck_at_one") return FaultType::StuckAtOne;
106	        return FaultType::Random;
107	    }
108	
109	    const char* 
110	    CHAOSReg::faultTypeToString(CHAOSReg::FaultType f) {
111	        switch (f) {
112	            case FaultType::BitFlip: return "bit_flip";
113	            case FaultType::StuckAtZero: return "stuck_at_zero";
114	            case FaultType::StuckAtOne: return "stuck_at_one";
115	        }
116	        return "random";
117	    }
118	    
119	    CHAOSReg::TargetClass 
120	    CHAOSReg::stringToTargetClass(const std::string &s) {
121	        if (s == "integer") return TargetClass::Integer;
122	        else if (s == "floating_point") return TargetClass::FloatingPoint;
123	        return TargetClass::Both;
124	    }
125	
126	    void 
127	    CHAOSReg::scheduleAttackEvent(Cycles delay)
128	    {
129	        if (!attackEvent.scheduled())
130	            schedule(attackEvent, cpu->clockEdge(delay));
131	    }
132	
133	    void 
134	    CHAOSReg::scheduleCheckPermanentFault(Cycles delay)
135	    {
136	        if (!periodicCheck.scheduled())
137	            schedule(periodicCheck, cpu->clockEdge(delay));
138	    }
139	
140	    void 
141	    CHAOSReg::unscheduleAttackEvent()
142	    {
143	        if (attackEvent.scheduled())
144	            attackEvent.squash();
145	
146	        if (periodicCheck.scheduled())
147	            periodicCheck.squash();
148	    }
149	
150	    int 
151	    CHAOSReg::generateRandomMask(std::mt19937 &gen, int bits_to_change, int len)
152	    {
153	        int mask = 0;
154	        std::uniform_int_distribution<int> bitDist(0, len-1);
155	
156	        while (bits_to_change-- > 0) {
157	            mask |= (1 << bitDist(gen));
158	        }
159	        return mask;
160	    }
161	
162	    void 
163	    CHAOSReg::processFault(ThreadID tid)
164	    {
165	        gem5::ThreadContext *thread_context = cpu->getContext(tid);
166	        if (!thread_context)
167	            return;
168	    
169	        gem5::BaseISA *isa = thread_context->getIsaPtr();
170	        if (!isa)
171	            return;
172	    
173	        const auto &reg_classes = isa->regClasses();
174	        const gem5::RegClass *reg_class = nullptr;
175	    
176	        if (reg_target_class_enum == TargetClass::Both) {
177	            int intRegs = reg_classes[gem5::IntRegClass]->numRegs();
178	            int floatRegs = reg_classes[gem5::FloatRegClass]->numRegs();
179	
180	            if (intRegs == 0 && floatRegs == 0) {
181	                warn("processFault: No registers found\n");
182	                return;
183	            } 
184	            if (intRegs > 0 && floatRegs == 0) {
185	                reg_class = reg_classes[gem5::IntRegClass];
186	            } else if (intRegs == 0 && floatRegs > 0) {
187	                reg_class = reg_classes[gem5::FloatRegClass];
188	            } else {
189	                reg_class = (rand() % 2 == 0) ? reg_classes[gem5::IntRegClass] : reg_classes[gem5::FloatRegClass];
190	            }
191	        } else if (reg_target_class_enum == TargetClass::Integer) {
192	            reg_class = reg_classes[gem5::IntRegClass];
193	            if (reg_class->numRegs() == 0) return;
194	        } else if (reg_target_class_enum == TargetClass::FloatingPoint) {
195	            reg_class = reg_classes[gem5::FloatRegClass];
196	            if (reg_class->numRegs() == 0) return;
197	        }
198	    
199	        if (!reg_class || reg_class->numRegs() == 0)
200	            return;
201	
202	        // Register index upper bound. The original code sampled over the full
203	        // numRegs() of the class, which on aarch64 IntRegClass includes:
204	        //   integer[31] = Zero (the zero register — injecting it has NO effect),
205	        //   integer[32+] = AArch32 banked-mode copies + non-architectural slots
206	        //   (not live in aarch64 user mode — injecting them has NO effect).
207	        // Both systematically inflate the Masked rate and underestimate SDC.
208	        // max_reg_idx (exclusive upper bound) lets the caller restrict to the
209	        // live architectural range; 0 = original full-range behavior.
210	        int num_regs = reg_class->numRegs();
211	        int upper = num_regs - 1;
212	        if (max_reg_idx > 0 && max_reg_idx < num_regs)
213	            upper = max_reg_idx - 1;
214	
215	        int random_reg = std::uniform_int_distribution<>(0, upper)(rng);
216	        gem5::RegId reg_id(*reg_class, random_reg);
217	        
218	        try {
219	            gem5::RegVal reg_val = thread_context->getReg(reg_id);
220	
221	            int mask = fault_mask.any() ? fault_mask.to_ulong() : generateRandomMask(rng, num_bits_to_change, sizeof(reg_val) << 3);
222	    
223	            FaultType chosen_fault_type_enum = fault_type_enum;
224	            if (fault_type_enum == FaultType::Random) {
225	                int faultIdx = random_fault_distribution(rng);
226	                chosen_fault_type_enum = static_cast<FaultType>(faultIdx);
227	            }
228	    
229	            switch (chosen_fault_type_enum) {
230	                case FaultType::StuckAtZero:
231	                    reg_val &= ~mask;
232	                    stats->numStuckAtZero++;
233	                    stats->numPermanentFaults++;
234	                    permanent_faults[std::make_pair(tid, reg_id)] = {chosen_fault_type_enum, mask, true};
235	                    break;
236	                case FaultType::StuckAtOne:
237	                    reg_val |= mask;
238	                    stats->numStuckAtOne++;
239	                    stats->numPermanentFaults++;
240	                    permanent_faults[std::make_pair(tid, reg_id)] = {chosen_fault_type_enum, mask, true};
241	                    break;
242	                case FaultType::BitFlip:
243	                    reg_val ^= mask;
244	                    stats->numBitFlips++;
245	                    break;
246	                default:
247	                    break;
248	            }
249	    
250	            thread_context->setReg(reg_id, reg_val);
251	            stats->numFaultsInjected++;
252	            ++faults_injected_count;
253	            
254	            if (write_log){
255	                *(log_stream->stream())  << "Cycle: " << cpu->curCycle()
256	                    << ", CPU: " << cpu->name()
257	                    << ", Thread: " << tid
258	                    << ", Register: " << reg_class->name() << "[" << random_reg << "]"
259	                    << ", FaultType: " << faultTypeToString(chosen_fault_type_enum)
260	                    << ", Mask: " << std::bitset<32>(mask)
261	                    << std::endl;
262	            }
263	
264	        } catch (const std::exception &e) {
