int 
CHAOSReg::generateRandomMask(std::mt19937 &gen, int bits_to_change, int len)
{
    int mask = 0;
    std::uniform_int_distribution<int> bitDist(0, len-1);

    while (bits_to_change-- > 0) {
        mask |= (1 << bitDist(gen));
    }
    return mask;
}

