/* G2 persistence kernel. Force the accumulator into a GPR with `register`
   asm, then storm it with writes. If stuck_at_one is armed on its phys
   reg, the low bits must read 1 after every write. We print the final
   value; if stuck_at_one 0xff changed the low byte, the golden (00000000deadbeef-
   derived) will differ (stuck proof). Print FINAL=<hex> to stderr. */
#include <unistd.h>
#include <stdint.h>

static void put_hex(unsigned long v){ char b[16]; for(int i=15;i>=0;--i){unsigned d=v&0xf;b[i]=d<10?'0'+d:'a'+d-10;v>>=4;} write(2,b,16); write(2,"\n",1);}

int main(void){
    register unsigned long x asm("x19") = 0;
    /* ROI write-storm on x19 */
    for (volatile unsigned long i=0;i<5000000UL;++i){
        x = i;
        x ^= 0xdeadbeefUL;
        /* x19 live-in-loop, prevent the compiler from spilling */
        asm volatile("" : "+r"(x) :: "memory");
    }
    put_hex(x);
    return 0;
}
