        statistics::Scalar numStuckAtZero;
        statistics::Scalar numStuckAtOne;
        statistics::Scalar numPermanentFaults;

        CHAOSMemStats(statistics::Group *parent);
      };

      std::unique_ptr<CHAOSMemStats> stats;
  };

} // namespace gem5

#endif // __MEM_CHAOSMem_HH__

